"use strict";const t=require("./request.js"),e=require("./urls.js"),o=require("./adapters.js");exports.applyJob=function(o){return t.post(e.API.jobApply(o))},exports.createJob=function(r){return t.post(e.API.jobs,o.toJobPayload(r))},exports.favoriteJob=function(o){return t.post(e.API.jobFavorite(o))},exports.getJobDetail=function(r){return t.get(e.API.jobDetail(r)).then(o.mapJob)},exports.getJobs=function(r){return t.get(e.API.jobs,r).then(t=>o.mapPage(t,o.mapJob))},exports.getMyJobs=function(r){return t.get(e.API.jobsMine,r).then(t=>o.mapPage(t,o.mapJob))},exports.updateJobStatus=function(o,r){return t.put(e.API.jobStatus(o),{status:"closed"===r?0:1})};
